10	export interface BuiltPool {
11	  /** Grader-facing rows: deduplicated, blinded order, no ranker/rank/score field. */
12	  entries: PoolEntry[];
13	  /** Scorer-only: each ranker's own ordered chunk_ref list, never shown to the grader. */
