17	/**
18	 * Forms the deduplicated union of both rankers' top-N hits for one query,
19	 * in an order that reveals nothing about which ranker(s) surfaced a chunk or
20	 * at what rank (the issue's blinding requirement): entries are sorted by
21	 * `chunk_ref` alone, which is neither ranker's own rank order and is
22	 * independent of relevance. `origins` records each ranker's real order
23	 * separately, read only by the scorer.
24	 */
25	export function buildPool(queryId: string, query: string, rankerHits: Record<RankerId, PoolSourceHit[]>): BuiltPool {
26	  const seen = new Map<string, PoolSourceHit>();
27	  for (const rankerId of RANKER_IDS) {
28	    for (const hit of rankerHits[rankerId]) {
29	      if (!seen.has(hit.chunk_ref)) seen.set(hit.chunk_ref, hit);
30	    }
31	  }
32	
33	  const entries: PoolEntry[] = [...seen.values()]
34	    .sort((a, b) => a.chunk_ref.localeCompare(b.chunk_ref))
35	    .map((hit) => ({ ...hit, query_id: queryId, query }));
36	
37	  const origins: QueryOrigins = {
38	    query_id: queryId,
39	    rankers: {
40	      bm25: rankerHits.bm25.map((h) => h.chunk_ref),
41	      weighted: rankerHits.weighted.map((h) => h.chunk_ref),
42	    },
43	  };
44	
45	  return { entries, origins };
46	}
